<?php
require_once __DIR__ . '/../../bootstrap.php';$u=require_auth(['super_admin','owner','admin','manager']);$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');
if($method==='GET'){$bid=business_scope($u,(int)($_GET['business_id']??0));$st=db()->prepare('SELECT id,audit_type,score,output,created_at FROM gmb_audits WHERE business_id=? ORDER BY created_at DESC LIMIT 30');$st->execute([$bid]);json_response(['ok'=>true,'audits'=>$st->fetchAll()]);}
require_method('POST');require_csrf();$d=request_json();$bid=business_scope($u,(int)($d['business_id']??0));$output=trim((string)($d['output']??''));if($output==='')json_response(['ok'=>false,'error'=>'Audit output is required'],422);$score=isset($d['score'])?max(0,min(100,(int)$d['score'])):null;$st=db()->prepare('INSERT INTO gmb_audits(business_id,audit_type,score,output) VALUES(?,?,?,?)');$st->execute([$bid,trim((string)($d['audit_type']??'local_rank'))?:'local_rank',$score,$output]);audit((int)$u['id'],$bid,'gmb_audit_saved',['audit_id'=>(int)db()->lastInsertId()]);json_response(['ok'=>true]);
